-- Run order (Supabase SQL Editor): 1) inmu_import.sql -> 2) catalog_cleanup.sql -> 3) food_search_names.sql -> 4) portion_setup_phase2.sql -> 5) add_doh_foods.sql -> 6) food_photos.sql
-- FitFast: food photos from Wikimedia Commons (free licences only).
-- Every photo was checked by eye to show the right dish. CC BY and CC BY-SA
-- require credit, so the app shows image_credit under the photo.
-- The link points at Wikimedia's own image server (hotlinking is allowed).
-- Run after catalog_cleanup.sql and add_doh_foods.sql. Safe to re-run.

alter table public.foods_catalog add column if not exists image_credit text;
alter table public.foods_catalog add column if not exists image_source_url text;

-- Photos copied from other websites without a licence are removed.
update public.foods_catalog
set image_url = null, image_credit = null, image_source_url = null
where image_url is not null
  and image_url not like 'https://upload.wikimedia.org/%'
  and image_url not like 'https://thumb.wikimedia.org/%';

with photos(food_code, image_url, image_credit, image_source_url) as (
