update public.foods_catalog f
set image_url = p.image_url,
    image_credit = p.image_credit,
    image_source_url = p.image_source_url
from photos p
where f.food_code = p.food_code;

select food_code, coalesce(common_name_th, name_th) as name, image_credit
from public.foods_catalog
where image_url is not null
order by food_code;
